<?php
declare(strict_types=1);
use DigiForge\POD\FC01OfflineConcept as Concept;
final class FC01OfflineConceptTest extends WP_UnitTestCase {
 private function input(array $changes=[]):array {return array_replace(['shop_key'=>'personalized_pod','family_id'=>'FC01','version'=>2,'spec_sha256'=>Concept::identity()['spec_sha256'],'family_name'=>'Mira & Léon','established'=>'2011'],$changes);}
 public function testApprovedDirectionHasIndependentlyTestableOfflineRenderer():void {self::assertTrue(class_exists(Concept::class),'FC01 v2 offline concept renderer is missing.');$r=Concept::render($this->input());self::assertNotWPError($r);self::assertSame('OUR FAMILY',$r['text_runs']['header']);self::assertSame('Mira & Léon',$r['text_runs']['family_name']);self::assertSame('ESTABLISHED 2011',$r['text_runs']['established']);self::assertSame('UNVERIFIED',$r['acceptance_state']);self::assertFalse($r['production_authorized']);self::assertSame('MISSING',$r['linguistic_review_state']);self::assertStringNotContainsString('SAMPLE PERSONALIZATION',$r['svg']);}
 public function testExactWhitespaceAndOptionalOmission():void {foreach([''," \t\n",'　']as $v){$r=Concept::render($this->input(['family_name'=>'  MiRa  ','established'=>$v]));self::assertNotWPError($r);self::assertSame('  MiRa  ',$r['text_runs']['family_name']);self::assertArrayNotHasKey('established',$r['text_runs']);}$i=$this->input();unset($i['established']);self::assertNotWPError(Concept::render($i));$r=Concept::render($this->input(['established'=>' 2011 ']));self::assertSame('ESTABLISHED  2011 ',$r['text_runs']['established']);}
 public function testLimitsCountCodePointsWithoutNormalization():void {$r=Concept::render($this->input(['family_name'=>str_repeat('é',48),'established'=>str_repeat('A',48)]));self::assertNotWPError($r);foreach(['family_name','established']as $field)self::assertWPError(Concept::render($this->input([$field=>str_repeat('é',49)])));self::assertWPError(Concept::render($this->input(['family_name'=>"Le\u{0301}on"])));self::assertWPError(Concept::render($this->input(['family_name'=>'Mira 😀'])));}
 public function testMissingBlankInvalidAndInjectedApprovalInputsDeny():void {foreach(['','  ',"\xff","a\nb"]as $s)self::assertWPError(Concept::render($this->input(['family_name'=>$s])));$i=$this->input();unset($i['family_name']);self::assertWPError(Concept::render($i));foreach([['shop_key'=>'digital'],['shop_key'=>'standard_pod'],['shop_key'=>'jewelry'],['version'=>1],['spec_sha256'=>str_repeat('0',64)],['review_approved'=>true],['locale_approved'=>true],['production_authorized'=>true],['template_id'=>'unapproved'],['locale'=>'en-US']]as $change)self::assertWPError(Concept::render($this->input($change)));}
 public function testEscapingAndNonoverlappingBoundedGeometry():void {$r=Concept::render($this->input(['family_name'=>"<script>&'\"</script>"]));self::assertNotWPError($r);self::assertSame("<script>&'\"</script>",$r['text_runs']['family_name']);self::assertStringNotContainsString('<script>',$r['svg']);self::assertNotWPError(DigiForge\POD\DeterministicPersonalizationRenderer::inspectSvg($r['svg']));$regions=$r['regions'];foreach($regions as $a)foreach($regions as $b)if($a!==$b)self::assertFalse($a['x']<$b['x']+$b['width']&&$b['x']<$a['x']+$a['width']&&$a['y']<$b['y']+$b['height']&&$b['y']<$a['y']+$a['height']);}
 /** @dataProvider invalidGeometry */
 public function testGeometryRejectsOverlapClippingAndOverflow(string $case):void {$p=dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/spec.json';$bytes=file_get_contents($p);$spec=json_decode($bytes,true);$input=$this->input();if($case==='overlap')$spec['regions']['ornament']['y']=530;elseif($case==='clipping')$spec['regions']['family_name']['x']=999;else $spec['regions']['family_name']['width']=1;$changed=json_encode($spec,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);try{file_put_contents($p,$changed);$input['spec_sha256']=hash('sha256',$changed);self::assertWPError(Concept::render($input));}finally{file_put_contents($p,$bytes);}}
 public static function invalidGeometry():array {return [['overlap'],['clipping'],['overflow']];}
 public function testTamperedSourceAndUnreviewedRetryCannotAcquireAuthority():void {$input=$this->input();$path=dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/ornament.png';$bytes=file_get_contents($path);try{file_put_contents($path,$bytes.'changed');$r=Concept::render($input);self::assertWPError($r);self::assertFalse($r->get_error_data()['external_execution_authorized']);self::assertSame($r->get_error_code(),Concept::render($input)->get_error_code());}finally{file_put_contents($path,$bytes);}self::assertSame('MISSING',Concept::render($input)['linguistic_review_state']);}
 public function testDisclaimerIsExternalToArtwork():void {$r=Concept::render($this->input());self::assertStringNotContainsString('CONCEPT ONLY',$r['svg']);$html=file_get_contents(dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/review.html');self::assertStringContainsString('OFFLINE CONCEPT ONLY',$html);self::assertStringContainsString('sample-preview.png',$html);self::assertStringNotContainsString('<script',$html);}
 public function testDeterminismV1ImmutabilityAndCommittedSample():void {$before=[];$root=dirname(__DIR__,2).'/assets/pod-designs/v1/';foreach(Concept::identity()['parent_sources']as $p=>$hash){self::assertSame($hash,hash_file('sha256',$root.$p));$before[$p]=$hash;}$r=Concept::render($this->input());$again=Concept::render($this->input());self::assertSame($r,$again);foreach($before as $p=>$hash)self::assertSame($hash,hash_file('sha256',$root.$p));self::assertSame(1,DigiForge\POD\DesignFamilyLibrary::inventory()['FC01']['version']);$dir=getenv('DF_FC01_CONCEPT_FIXTURE_DIR');if($dir){foreach(['svg','png']as $format)foreach(['preview','final']as $kind)file_put_contents($dir.'/sample-'.$kind.'.'.$format,$r[$format]);file_put_contents($dir.'/provenance.json',json_encode(['fictional_sample_only'=>true,'owner_direction'=>'FC01 v2 Option A Clear Center; offline engineering only','proposed_review_locale'=>'en-US','locale_approved'=>false,'production_template_binding'=>'UNKNOWN','input'=>$this->input(),'identity'=>Concept::identity(),'review_overlay_sha256'=>hash_file('sha256',dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/review.html'),'renderer_sha256'=>hash_file('sha256',dirname(__DIR__,2).'/includes/POD/FC01OfflineConcept.php'),'text_runs'=>$r['text_runs'],'acceptance_state'=>'UNVERIFIED','linguistic_review_state'=>'MISSING','rights_certified'=>false,'production_authorized'=>false,'artifacts'=>array_combine(['sample-preview.svg','sample-final.svg','sample-preview.png','sample-final.png'],[hash('sha256',$r['svg']),hash('sha256',$r['svg']),hash('sha256',$r['png']),hash('sha256',$r['png'])])],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n");}else{$d=dirname(__DIR__,2).'/assets/pod-designs/fc01-v2/';$m=json_decode(file_get_contents($d.'provenance.json'),true);self::assertSame(Concept::identity(),$m['identity']);self::assertSame($m['renderer_sha256'],hash_file('sha256',dirname(__DIR__,2).'/includes/POD/FC01OfflineConcept.php'));self::assertSame($m['review_overlay_sha256'],hash_file('sha256',$d.'review.html'));foreach(['svg','png']as $format)foreach(['preview','final']as $kind){$p='sample-'.$kind.'.'.$format;self::assertSame($r[$format],file_get_contents($d.$p));self::assertSame($m['artifacts'][$p],hash_file('sha256',$d.$p));}}}
}
